DROP TABLE IF EXISTS `live_analysis_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `live_analysis_reports` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '报告ID',
  `live_stream_id` bigint NOT NULL COMMENT '直播ID',
  `report_content` mediumtext NOT NULL COMMENT 'AI分析报告内容',
  `ai_provider` varchar(255) DEFAULT NULL COMMENT 'AI服务提供方',
  `prompt_snapshot` text COMMENT '生成报告时的提示词快照',
  `generated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次生成时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `live_stream_id` (`live_stream_id`),
  KEY `idx_analysis_stream` (`live_stream_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='直播分析报告表';
