DROP TABLE IF EXISTS `live_feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `live_feedback` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '反馈ID',
  `live_stream_id` bigint NOT NULL COMMENT '直播ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `user_name` varchar(100) NOT NULL COMMENT '用户名',
  `user_role` varchar(20) DEFAULT 'student' COMMENT '用户角色',
  `phase` varchar(20) DEFAULT 'live' COMMENT '反馈阶段: live/post',
  `content` text NOT NULL COMMENT '反馈内容',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  PRIMARY KEY (`id`),
  KEY `idx_feedback_stream` (`live_stream_id`),
  KEY `idx_feedback_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='直播反馈表';
/*!40101 SET character_set_client = @saved_cs_client */;

