--
-- Table structure for table `live_streams`
--

DROP TABLE IF EXISTS `live_streams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `live_streams` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL COMMENT '直播标题',
  `description` text COMMENT '直播描述',
  `teacher_id` bigint NOT NULL COMMENT '教师ID',
  `teacher_name` varchar(100) NOT NULL COMMENT '教师姓名',
  `course_id` bigint DEFAULT NULL COMMENT '关联课程ID',
  `course_name` varchar(200) DEFAULT NULL COMMENT '课程名称',
  `status` enum('scheduled','live','ended') DEFAULT 'scheduled' COMMENT '状态',
  `stream_key` varchar(100) DEFAULT NULL COMMENT '推流密钥',
  `stream_url` varchar(500) DEFAULT NULL COMMENT '推流地址',
  `play_url` varchar(500) DEFAULT NULL COMMENT '播放地址',
  `cover_image` varchar(500) DEFAULT NULL COMMENT '封面图片',
  `scheduled_time` datetime DEFAULT NULL COMMENT '预定开始时间',
  `start_time` datetime DEFAULT NULL COMMENT '实际开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `viewer_count` int DEFAULT '0' COMMENT '当前观看人数',
  `total_views` int DEFAULT '0' COMMENT '累计观看次数',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_teacher_id` (`teacher_id`),
  KEY `idx_course_id` (`course_id`),
  KEY `idx_status` (`status`),
  KEY `idx_scheduled_time` (`scheduled_time`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='直播表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
