-- Dumping data for table `tb_admin_role`
--

LOCK TABLES `tb_admin_role` WRITE;
/*!40000 ALTER TABLE `tb_admin_role` DISABLE KEYS */;
INSERT INTO `tb_admin_role` VALUES (1,'超级管理员',5,'系统最高权限,拥有所有操作权限','[\"user:*\", \"course:*\", \"resource:*\", \"announcement:*\", \"system:*\", \"admin:*\"]',1,'2025-12-23 18:31:35'),(2,'日志管理员',4,'负责管理redis和所有日志','[\"user:view\", \"course:view\", \"resource:view\", \"system:*\", \"monitor:*\"]',1,'2025-12-23 18:31:35'),(3,'教务管理员',3,'教务处工作人员,管理教学相关业务','[\"user:*\", \"course:*\", \"resource:approve\", \"resource:delete\", \"announcement:*\", \"schedule:*\"]',1,'2025-12-23 18:31:35'),(4,'资源管理员',2,'内容审核人员,负责资源和公告审核','[\"resource:view\", \"resource:approve\", \"resource:delete\", \"announcement:create\", \"announcement:edit\"]',1,'2025-12-23 18:31:35');
/*!40000 ALTER TABLE `tb_admin_role` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `tb_ai_chat_history`
--

DROP TABLE IF EXISTS `tb_ai_chat_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_ai_chat_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `role` varchar(20) NOT NULL COMMENT '用户角色：student/teacher/admin',
  `message` text COMMENT '消息内容',
  `is_user` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否为用户消息：1-用户消息，0-AI回复',
  `session_id` varchar(100) NOT NULL COMMENT '会话ID',
  `session_title` varchar(200) DEFAULT '新对话' COMMENT '会话标题',
  `first_message` varchar(500) DEFAULT NULL COMMENT '会话首条消息，用于历史列表显示',
  `file_path` varchar(500) DEFAULT NULL COMMENT '附件文件路径（如果有）',
  `file_type` varchar(50) DEFAULT NULL COMMENT '附件类型：word/pdf/image/excel/txt',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_role_session` (`user_id`,`role`,`session_id`),
  KEY `idx_session` (`session_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=283 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI聊天历史记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

