DROP TABLE IF EXISTS `tb_announcement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_announcement` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '公告ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告标题',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告内容',
  `type` enum('system','course','exam','other') COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '公告类型',
  `priority` enum('low','medium','high') COLLATE utf8mb4_unicode_ci DEFAULT 'medium' COMMENT '优先级',
  `target_role` enum('all','student','teacher','admin') COLLATE utf8mb4_unicode_ci DEFAULT 'all' COMMENT '目标角色',
  `publisher_id` bigint NOT NULL COMMENT '发布者ID',
  `publisher_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布者姓名(冗余)',
  `publish_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `status` enum('draft','published','archived') COLLATE utf8mb4_unicode_ci DEFAULT 'published' COMMENT '状态',
  PRIMARY KEY (`id`),
  KEY `idx_type_status` (`type`,`status`),
  KEY `idx_target_role` (`target_role`),
  KEY `idx_publish_time` (`publish_time` DESC),
  KEY `idx_priority_status` (`priority`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公告通知表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `tb_announcement`
--

LOCK TABLES `tb_announcement` WRITE;
/*!40000 ALTER TABLE `tb_announcement` DISABLE KEYS */;
INSERT INTO `tb_announcement` VALUES (1,'2025-2026学年第一学期选课通','各位同学：\n\n本学期选课时间为11月20日-11月30日，请及时登录系统进行选课。\n\n教务处\n2025年11月15','course','high','student',1,'系统管理员','2025-11-26 22:33:04','published'),(2,'系统维护通知','系统将于本周六（11月23日）凌晨2:00-5:00进行维护升级，期间将无法访问，请各位用户合理安排时间。','system','medium','all',1,'系统管理员','2025-11-26 22:33:04','published'),(4,'这是一个友好的测试。','超级哟好','system','medium','all',1,'系统管理','2025-12-05 08:51:51','published');
/*!40000 ALTER TABLE `tb_announcement` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `tb_code_submission`
--

DROP TABLE IF EXISTS `tb_code_submission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_code_submission` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '提交ID',
  `experiment_id` bigint NOT NULL COMMENT '实验ID',
  `experiment_problem_id` bigint NOT NULL COMMENT '实验题目ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `student_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学生姓名(冗余)',
  `language` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编程语言(如 python3, java, cpp)',
  `code` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提交的源代码',
  `stdin` text COLLATE utf8mb4_unicode_ci COMMENT '本次提交用于测试的输入(若为样例点则对应样例输入)',
  `expected_output` text COLLATE utf8mb4_unicode_ci COMMENT '期望输出(用于样例比对)',
  `stdout` text COLLATE utf8mb4_unicode_ci COMMENT '执行stdout',
  `stderr` text COLLATE utf8mb4_unicode_ci COMMENT '执行stderr/错误信息',
  `piston_response` json DEFAULT NULL COMMENT 'Piston 原始响应(JSON)',
  `result` enum('AC','WA','TLE','RE','CE','PE','UNKNOWN') COLLATE utf8mb4_unicode_ci DEFAULT 'UNKNOWN' COMMENT '判题结果(AC/WA/超时/运行错误/编译错误/输出不完全)',
  `run_time_ms` int DEFAULT NULL COMMENT '运行耗时(ms)',
  `memory_kb` int DEFAULT NULL COMMENT '使用内存(kB)',
  `submit_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  PRIMARY KEY (`id`),
  KEY `idx_experiment_problem` (`experiment_problem_id`),
  KEY `idx_student_id` (`student_id`),
  KEY `idx_result` (`result`),
  KEY `idx_submit_time` (`submit_time`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='代码提交记录表(含Piston响应)';
