DROP TABLE IF EXISTS `tb_learning_progress`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_learning_progress` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '进度ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `resource_id` bigint DEFAULT NULL COMMENT '资源ID',
  `resource_type` enum('video','document','code','other') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源类型',
  `progress_percent` int DEFAULT '0' COMMENT '完成百分比',
  `duration_seconds` int DEFAULT '0' COMMENT '学习时长(秒)',
  `last_position` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后位置(视频进度/文档页码)',
  `is_completed` tinyint(1) DEFAULT '0' COMMENT '是否完成',
  `complete_time` datetime DEFAULT NULL COMMENT '完成时间',
  `last_study_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后学习时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_resource` (`student_id`,`resource_id`),
  KEY `idx_student_course` (`student_id`,`course_id`),
  KEY `idx_resource_id` (`resource_id`),
  KEY `idx_student_complete` (`student_id`,`is_completed`),
  KEY `idx_last_study_time` (`last_study_time` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='学习进度表';
