--
-- Table structure for table `tb_question_bank`
--

DROP TABLE IF EXISTS `tb_question_bank`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_question_bank` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '题目ID',
  `course_id` bigint DEFAULT NULL COMMENT '关联课程ID(可为空表示通用题库)',
  `question_type` enum('single_choice','multiple_choice','true_false','fill_blank','short_answer','programming') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目类型',
  `difficulty` enum('easy','medium','hard') COLLATE utf8mb4_unicode_ci DEFAULT 'medium' COMMENT '难度',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目内容',
  `options` json DEFAULT NULL COMMENT '选项(JSON数组,仅选择题使用)',
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '正确答案',
  `explanation` text COLLATE utf8mb4_unicode_ci COMMENT '答案解析',
  `score` int NOT NULL DEFAULT '5' COMMENT '默认分值',
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签(逗号分隔)',
  `knowledge_points` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '知识点',
  `usage_count` int DEFAULT '0' COMMENT '使用次数',
  `creator_id` bigint NOT NULL COMMENT '创建者ID',
  `creator_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建者姓名(冗余)',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci DEFAULT 'active' COMMENT '状态',
  `is_visible` int NOT NULL DEFAULT '1' COMMENT '学生是否可见(1=可见,0=不可见,教师全部可见)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_course_id` (`course_id`),
  KEY `idx_type_difficulty` (`question_type`,`difficulty`),
  KEY `idx_creator_id` (`creator_id`),
  KEY `idx_course_type` (`course_id`,`question_type`),
  KEY `idx_difficulty` (`difficulty`),
  KEY `idx_usage_count` (`usage_count` DESC),
  KEY `idx_is_visible` (`is_visible`),
  FULLTEXT KEY `idx_fulltext_content` (`content`)
) ENGINE=InnoDB AUTO_INCREMENT=359 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='题库表';
/*!40101 SET character_set_client = @saved_cs_client */;

