--
-- Table structure for table `tb_resource`
--

DROP TABLE IF EXISTS `tb_resource`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_resource` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '资源ID',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `course_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '课程名称(冗余)',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源名称',
  `type` enum('document','video','code','other') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源类型',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '资源描述',
  `file_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文件URL(OSS)',
  `preview_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PDF棰勮?鏂囦欢URL',
  `file_size` bigint NOT NULL COMMENT '文件大小(字节)',
  `uploader_id` bigint NOT NULL COMMENT '上传者ID',
  `uploader_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上传者姓名(冗余)',
  `download_count` int DEFAULT '0' COMMENT '下载次数',
  `tags` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签(逗号分隔)',
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '审核状态',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  PRIMARY KEY (`id`),
  KEY `idx_course_id` (`course_id`),
  KEY `idx_type_status` (`type`,`status`),
  KEY `idx_uploader_id` (`uploader_id`),
  KEY `idx_create_time` (`create_time` DESC),
  FULLTEXT KEY `idx_fulltext_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教学资源表';
/*!40101 SET character_set_client = @saved_cs_client */;

