-- Table structure for table `tb_student_exam`
--

DROP TABLE IF EXISTS `tb_student_exam`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_student_exam` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '考试记录ID',
  `exam_paper_id` bigint NOT NULL COMMENT '试卷ID',
  `student_id` bigint NOT NULL COMMENT '学生ID',
  `student_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学生姓名(冗余)',
  `student_number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学号(冗余)',
  `attempt_number` int NOT NULL DEFAULT '1' COMMENT '尝试次数',
  `start_time` datetime DEFAULT NULL COMMENT '开始答题时间',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `total_score` int DEFAULT NULL COMMENT '总得分',
  `objective_score` int DEFAULT NULL COMMENT '客观题得分(自动批改)',
  `subjective_score` int DEFAULT NULL COMMENT '主观题得分(教师批改)',
  `status` enum('not_started','in_progress','submitted','graded') COLLATE utf8mb4_unicode_ci DEFAULT 'not_started' COMMENT '考试状态',
  `ip_address` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP地址',
  `answer_sheet` json DEFAULT NULL COMMENT '答题卡(JSON对象)',
  `grader_id` bigint DEFAULT NULL COMMENT '批改者ID',
  `grader_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批改者姓名',
  `grade_time` datetime DEFAULT NULL COMMENT '批改时间',
  `feedback` text COLLATE utf8mb4_unicode_ci COMMENT '评语',
  `duration` int DEFAULT NULL COMMENT '考试时长(分钟)',
  `pass_score` int DEFAULT NULL COMMENT '及格分数',
  PRIMARY KEY (`id`),
  KEY `idx_student_id` (`student_id`),
  KEY `idx_status` (`status`),
